import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Tensor-core implicit-GEMM convolution. Each CTA computes a 64x32 tile:
// 64 spatial outputs for all 32 output channels. The 64x32 im2col operand
// and the 32x32 zero-padded weight operand are staged in shared memory,
// then sixteen warps evaluate the tile with bf16 m16n8k16 MMA operations
// and FP32 accumulation. Accumulators are exchanged through shared memory
// so final stores are coalesced 32-bit pairs over spatial output elements.
.extern .shared .align 16 .b8 smem_raw[];
.visible .entry conv2d_bf16_3x3(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_out
)
{
    .reg .pred %p;
    .reg .b16 %h0;
    .reg .b32 %a<4>, %b<2>, %r_pack;
    .reg .f32 %d<4>;
    .reg .u32 %r_tid, %r_lane, %r_warp, %r_group, %r_tig;
    .reg .u32 %r_warp_m, %r_warp_n, %r_m0, %r_n;
    .reg .u32 %r_i, %r_e, %r_m, %r_k, %r_pidx, %r_oh, %r_ow;
    .reg .u32 %r_c, %r_kh, %r_kw, %r_ih, %r_iw, %r_oc;
    .reg .u32 %r_off, %r_tmp, %r_sbase, %r_sb, %r_saddr;
    .reg .u32 %r_aoff, %r_boff, %r_coff, %r_pair;
    .reg .u64 %rd_in, %rd_w, %rd_out, %rd_addr;
    ld.param.u64 %rd_in, [param_in];
    ld.param.u64 %rd_w, [param_w];
    ld.param.u64 %rd_out, [param_out];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_m0, %ctaid.x;
    mul.lo.u32 %r_m0, %r_m0, 64;
    mov.u32 %r_n, %ctaid.z;
    mov.u32 %r_sbase, smem_raw;
    add.u32 %r_sb, %r_sbase, 4096;
    // Stage a 64x32 im2col A tile. k = ic*9 + kh*3 + kw; k 27..31 is zero.
    mov.u32 %r_i, 0;
A_LOOP:
    setp.ge.u32 %p, %r_i, 4;
    @%p bra A_DONE;
    mad.lo.u32 %r_e, %r_i, 512, %r_tid;
    div.u32 %r_m, %r_e, 32;
    rem.u32 %r_k, %r_e, 32;
    mov.b16 %h0, 0;
    setp.ge.u32 %p, %r_k, 27;
    @%p bra A_STORE;
    add.u32 %r_pidx, %r_m0, %r_m;
    setp.ge.u32 %p, %r_pidx, 49284;
    @%p bra A_STORE;
    div.u32 %r_oh, %r_pidx, 222;
    rem.u32 %r_ow, %r_pidx, 222;
    div.u32 %r_c, %r_k, 9;
    rem.u32 %r_tmp, %r_k, 9;
    div.u32 %r_kh, %r_tmp, 3;
    rem.u32 %r_kw, %r_tmp, 3;
    add.u32 %r_ih, %r_oh, %r_kh;
    add.u32 %r_iw, %r_ow, %r_kw;
    mul.lo.u32 %r_off, %r_n, 150528;
    mad.lo.u32 %r_off, %r_c, 50176, %r_off;
    mad.lo.u32 %r_off, %r_ih, 224, %r_off;
    add.u32 %r_off, %r_off, %r_iw;
    mul.wide.u32 %rd_addr, %r_off, 2;
    add.u64 %rd_addr, %rd_in, %rd_addr;
    ld.global.b16 %h0, [%rd_addr];
A_STORE:
    mad.lo.u32 %r_saddr, %r_e, 2, %r_sbase;
    st.shared.b16 [%r_saddr], %h0;
    add.u32 %r_i, %r_i, 1;
    bra A_LOOP;
A_DONE:
    // Stage B in column-major KxN order as B[oc][k], zeroing k 27..31.
    mov.u32 %r_i, 0;
W_LOOP:
    setp.ge.u32 %p, %r_i, 2;
    @%p bra W_DONE;
    mad.lo.u32 %r_e, %r_i, 512, %r_tid;
    div.u32 %r_oc, %r_e, 32;
    rem.u32 %r_k, %r_e, 32;
    mov.b16 %h0, 0;
    setp.ge.u32 %p, %r_k, 27;
    @%p bra W_STORE;
    mad.lo.u32 %r_off, %r_oc, 27, %r_k;
    mul.wide.u32 %rd_addr, %r_off, 2;
    add.u64 %rd_addr, %rd_w, %rd_addr;
    ld.global.b16 %h0, [%rd_addr];
W_STORE:
    mad.lo.u32 %r_saddr, %r_e, 2, %r_sb;
    st.shared.b16 [%r_saddr], %h0;
    add.u32 %r_i, %r_i, 1;
    bra W_LOOP;
W_DONE:
    bar.sync 0;
    // Sixteen warps form a 4x4 array of m16n8 tiles.
    and.b32 %r_lane, %r_tid, 31;
    shr.u32 %r_warp, %r_tid, 5;
    shr.u32 %r_group, %r_lane, 2;
    and.b32 %r_tig, %r_lane, 3;
    shr.u32 %r_warp_m, %r_warp, 2;
    and.b32 %r_warp_n, %r_warp, 3;
    // A row-major fragment addresses for the first k16 chunk.
    mul.lo.u32 %r_aoff, %r_warp_m, 1024;
    mad.lo.u32 %r_aoff, %r_group, 64, %r_aoff;
    mad.lo.u32 %r_aoff, %r_tig, 4, %r_aoff;
    add.u32 %r_aoff, %r_aoff, %r_sbase;
    ld.shared.b32 %a0, [%r_aoff+0];
    ld.shared.b32 %a1, [%r_aoff+512];
    ld.shared.b32 %a2, [%r_aoff+16];
    ld.shared.b32 %a3, [%r_aoff+528];
    // B column-major fragment addresses for the first k16 chunk.
    mul.lo.u32 %r_boff, %r_warp_n, 512;
    mad.lo.u32 %r_boff, %r_group, 64, %r_boff;
    mad.lo.u32 %r_boff, %r_tig, 4, %r_boff;
    add.u32 %r_boff, %r_boff, %r_sb;
    ld.shared.b32 %b0, [%r_boff+0];
    ld.shared.b32 %b1, [%r_boff+16];
    mov.f32 %d0, 0f00000000;
    mov.f32 %d1, 0f00000000;
    mov.f32 %d2, 0f00000000;
    mov.f32 %d3, 0f00000000;
    mma.sync.aligned.m16n8k16.row.col.f32.bf16.bf16.f32
        {%d0, %d1, %d2, %d3},
        {%a0, %a1, %a2, %a3},
        {%b0, %b1},
        {%d0, %d1, %d2, %d3};
    // Advance both operands by 16 k-elements (32 bytes) and accumulate.
    add.u32 %r_aoff, %r_aoff, 32;
    add.u32 %r_boff, %r_boff, 32;
    ld.shared.b32 %a0, [%r_aoff+0];
    ld.shared.b32 %a1, [%r_aoff+512];
    ld.shared.b32 %a2, [%r_aoff+16];
    ld.shared.b32 %a3, [%r_aoff+528];
    ld.shared.b32 %b0, [%r_boff+0];
    ld.shared.b32 %b1, [%r_boff+16];
    mma.sync.aligned.m16n8k16.row.col.f32.bf16.bf16.f32
        {%d0, %d1, %d2, %d3},
        {%a0, %a1, %a2, %a3},
        {%b0, %b1},
        {%d0, %d1, %d2, %d3};
    // Ensure all operand reads are complete before reusing shared memory as
    // a 32x64 output-channel-major staging buffer for coalesced stores.
    bar.sync 0;
    mul.lo.u32 %r_oc, %r_warp_n, 8;
    mad.lo.u32 %r_oc, %r_tig, 2, %r_oc;
    mul.lo.u32 %r_m, %r_warp_m, 16;
    add.u32 %r_m, %r_m, %r_group;
    mul.lo.u32 %r_coff, %r_oc, 128;
    mad.lo.u32 %r_coff, %r_m, 2, %r_coff;
    add.u32 %r_coff, %r_coff, %r_sbase;
    cvt.rn.bf16.f32 %h0, %d0;
    st.shared.b16 [%r_coff+0], %h0;
    cvt.rn.bf16.f32 %h0, %d1;
    st.shared.b16 [%r_coff+128], %h0;
    cvt.rn.bf16.f32 %h0, %d2;
    st.shared.b16 [%r_coff+16], %h0;
    cvt.rn.bf16.f32 %h0, %d3;
    st.shared.b16 [%r_coff+144], %h0;
    bar.sync 0;
    // Copy 32 channels x 64 spatial positions as aligned bf16 pairs.
    mov.u32 %r_i, 0;
OUT_LOOP:
    setp.ge.u32 %p, %r_i, 2;
    @%p bra OUT_DONE;
    mad.lo.u32 %r_e, %r_i, 512, %r_tid;
    div.u32 %r_oc, %r_e, 32;
    rem.u32 %r_pair, %r_e, 32;
    mul.lo.u32 %r_m, %r_pair, 2;
    add.u32 %r_pidx, %r_m0, %r_m;
    setp.ge.u32 %p, %r_pidx, 49284;
    @%p bra OUT_NEXT;
    mul.lo.u32 %r_saddr, %r_oc, 128;
    mad.lo.u32 %r_saddr, %r_m, 2, %r_saddr;
    add.u32 %r_saddr, %r_saddr, %r_sbase;
    ld.shared.b32 %r_pack, [%r_saddr];
    mul.lo.u32 %r_off, %r_n, 1577088;
    mad.lo.u32 %r_off, %r_oc, 49284, %r_off;
    add.u32 %r_off, %r_off, %r_pidx;
    mul.wide.u32 %rd_addr, %r_off, 2;
    add.u64 %rd_addr, %rd_out, %rd_addr;
    st.global.b32 [%rd_addr], %r_pack;
OUT_NEXT:
    add.u32 %r_i, %r_i, 1;
    bra OUT_LOOP;
OUT_DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_bf16_3x3")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)

    def forward(self, x):
        weight = self.conv1.weight
        n = x.shape[0]
        oc = weight.shape[0]
        ho = x.shape[2] - 2
        wo = x.shape[3] - 2
        out = torch.empty((n, oc, ho, wo), dtype=x.dtype, device=x.device)
        total = out.numel()
        module = _get_ptx_module()
        block = 512
        tiles_m = (ho * wo + 63) // 64
        grid = (tiles_m, 1, n)
        module.launch(
            "conv2d_bf16_3x3",
            grid=grid,
            block=(block, 1, 1),
            arguments=[x, weight, out],
            shared_memory=6144,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

